const { telegram_id, product_id, quantity, delivery_address } = $json;

const productId = Number(product_id);
const qty = Number(quantity);
const telegramId = String(telegram_id ?? '');

if (!/^\d+$/.test(telegramId)) {
  throw new Error('Invalid Telegram customer ID');
}

if (!Number.isSafeInteger(productId) || productId <= 0) {
  throw new Error('Invalid product ID');
}

if (!Number.isSafeInteger(qty) || qty < 1 || qty > 20) {
  throw new Error('Quantity must be between 1 and 20');
}

if (
  typeof delivery_address !== 'string' ||
  delivery_address.trim().length < 10
) {
  throw new Error('A valid delivery address is required');
}

return {
  json: {
    telegram_id: telegramId,
    product_id: productId,
    quantity: qty,
    delivery_address: delivery_address.trim()
  }
};

